// The server copy (supabase/functions/_shared/gamedata.json) must equal the app data (src/data/*)
// and the committed adjacency.v1.json. Both are generated by gen-puzzles.ts; never hand-edit either.
// Also re-checks the schedule invariants (V4) on the files as written.
import { isDeepStrictEqual } from 'node:util';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import type { Adjacency, DailySchedule, Puzzle, Region } from '../supabase/functions/_shared/engine/types.ts';
import { shortestDistance } from '../supabase/functions/_shared/engine/graph.ts';
import { addDays } from '../supabase/functions/_shared/engine/time.ts';
import { ADJACENCY_VERSION, fail, loadAdjacency, p, readJson } from './lib/common.ts';

const app = {
  regions: readJson<Region[]>(p('src/data/regions.json')),
  adjacency: readJson<Adjacency>(p('src/data/adjacency.json')),
  puzzles: readJson<Puzzle[]>(p('src/data/puzzles.json')),
  daily: readJson<DailySchedule>(p('src/data/daily.json')),
};
const server = readJson<typeof app & { adjacencyVersion: number }>(p('supabase/functions/_shared/gamedata.json'));

const errors: string[] = [];
if (server.adjacencyVersion !== ADJACENCY_VERSION) errors.push(`gamedata adjacencyVersion ${server.adjacencyVersion} ≠ ${ADJACENCY_VERSION}`);
for (const key of ['regions', 'adjacency', 'puzzles', 'daily'] as const)
  if (!isDeepStrictEqual(app[key], server[key])) errors.push(`gamedata.json "${key}" differs from src/data/${key}.json`);
if (!isDeepStrictEqual(app.adjacency, loadAdjacency())) errors.push('src/data/adjacency.json differs from data/adjacency.v1.json');

// V1 / V4 on the written files.
const kind = new Map(app.regions.map((r) => [r.id, r.kind]));
const puzzleById = new Map(app.puzzles.map((pz) => [pz.id, pz]));
for (const pz of app.puzzles) {
  if (pz.start === pz.end || kind.get(pz.start) !== 'state' || kind.get(pz.end) !== 'state') errors.push(`puzzle ${pz.id}: ends must be distinct states`);
  if (pz.k < 2 || pz.k > 6) errors.push(`puzzle ${pz.id}: k=${pz.k} out of range`);
  if (shortestDistance(pz.start, pz.end, app.adjacency) - 1 !== pz.k) errors.push(`puzzle ${pz.id}: stored k ≠ BFS distance`);
  for (let i = 0; i + 1 < pz.shortest.length; i++)
    if (!app.adjacency[pz.shortest[i]]?.includes(pz.shortest[i + 1])) errors.push(`puzzle ${pz.id}: route edge ${pz.shortest[i]}-${pz.shortest[i + 1]} missing`);
}
const seen = new Map<string, string>();
app.daily.entries.forEach((e, i) => {
  if (i > 0 && e.date !== addDays(app.daily.entries[i - 1].date, 1)) errors.push(`daily: ${e.date} does not follow ${app.daily.entries[i - 1].date}`);
  if (!puzzleById.has(e.puzzleId)) errors.push(`daily ${e.date}: unknown puzzle ${e.puzzleId}`);
  const last = seen.get(e.puzzleId);
  if (last && addDays(last, 60) > e.date) errors.push(`daily ${e.date}: ${e.puzzleId} repeats within 60 days (last ${last})`);
  seen.set(e.puzzleId, e.date);
});

if (errors.length) fail(`Data out of sync / invalid:\n  - ${errors.slice(0, 20).join('\n  - ')}`);
const hash = createHash('sha256').update(readFileSync(p('supabase/functions/_shared/gamedata.json'))).digest('hex').slice(0, 12);
console.log(`✓ gamedata.json in sync with src/data (sha256 ${hash}); ${app.puzzles.length} puzzles, ${app.daily.entries.length} daily dates valid`);
